import { ActionType, Hooks, TableInstance, TableState } from 'react-table';

/** Reducer that handles the toggling of sorting of a column */
function sortChangeReducer(
  state: TableState,
  action: ActionType,
  _previousState?: TableState,
  _instance?: TableInstance,
) {
  if (_instance) {
    const { disableSortBy, onSortChange } = _instance;

    if (!disableSortBy && typeof onSortChange === 'function') {
      if (action.type === 'toggleSortBy' || action.type === 'clearSortBy') {
        const { sortBy } = state;
        requestAnimationFrame(() => {
          if (sortBy.length === 0) {
            onSortChange(action.columnId, 'unset');
          } else {
            onSortChange(
              action.columnId,
              sortBy[0].desc ? 'descending' : 'ascending',
            );
          }
        });
      }

      return state;
    }
  }
}

/**
 * Hook for triggering the sort change handler when a column gets sorted
 */
export function useSortChangeHandler(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  hooks: Hooks<any>,
): void {
  hooks.stateReducers.push(sortChangeReducer);
}

useSortChangeHandler.pluginName = 'useSortChangeHandler';
